import{_ as l,a0 as r,w as o,s as p,ao as g,I as n,x as e,a1 as a,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"管理大型 Postgres 数据库的 3 个技巧 | LCTT x X-CMD","titleTemplate":false,"description":"管理大型 Postgres 数据库的 3 个技巧 | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"管理大型 Postgres 数据库的 3 个技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"管理大型 Postgres 数据库的 3 个技巧 | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230228.2 ⭐️ 3 tips to manage large Postgres databases","title":"管理大型 Postgres 数据库的 3 个技巧","tag":"202303","desc":""},"relativePath":"202303/20230228.2 ⭐️ 3 tips to manage large Postgres databases.md","filePath":"[post].md"}'),d={name:"202303/20230228.2 ⭐️ 3 tips to manage large Postgres databases.md"};function h(k,s,b,c,u,m){const t=r("Link");return o(),p("div",null,[s[15]||(s[15]=g('<h1 id="管理大型-postgres-数据库的-3-个技巧" tabindex="-1">管理大型 Postgres 数据库的 3 个技巧 <a class="header-anchor" href="#管理大型-postgres-数据库的-3-个技巧" aria-label="Permalink to “管理大型 Postgres 数据库的 3 个技巧”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202303/06/113049bkunsxun1clzuca8.jpg" alt=""></p><blockquote><p>在处理庞大的数据库时，请尝试这些方便的解决方案，以解决常见的问题。</p></blockquote><p>关系型数据库 PostgreSQL（也被称为 Postgres）已经越来越流行，全球各地的企业和公共部门都在使用它。随着这种广泛的采用，数据库已经变得比以前更大了。在 Crunchy Data，我们经常与 20TB 以上的数据库打交道，而且我们现有的数据库还在继续增长。我的同事 David Christensen 和我收集了一些关于管理拥有巨大表的数据库的技巧。</p><h3 id="大表" tabindex="-1">大表 <a class="header-anchor" href="#大表" aria-label="Permalink to “大表”">​</a></h3><p>生产数据库通常由许多具有不同数据、大小和模式的表组成。常见的情况是，最终有一个巨大的、无序的数据库表，远远大于你数据库中的任何其他表。这个表经常存储活动日志或有时间戳的事件，而且对你的应用或用户来说是必要的。</p><p>真正的大表会因为很多原因造成挑战，但一个常见的原因是锁。对表的定期维护往往需要锁，但对大表的锁可能会使你的应用瘫痪，或导致堵塞和许多令人头痛的问题。我有一些做基本维护的技巧，比如添加列或索引，同时避免长期运行的锁。</p><p><strong>添加索引的问题</strong>：在创建索引的过程中锁住表。如果你有一个庞大的表，这可能需要几个小时。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE INDEX ON customers (last_name)</span></span></code></pre></div><p><strong>方案</strong>：使用 <code>CREATE INDEX CONCURRENTLY</code> 功能。这种方法将索引创建分成两部分，一部分是短暂的锁定，以创建索引，立即开始跟踪变化，但尽量减少应用阻塞，然后是完全建立该索引，之后查询可以开始使用它。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>CREATE INDEX CONCURRENTLY ON customers (last_name)</span></span></code></pre></div><h3 id="添加列" tabindex="-1">添加列 <a class="header-anchor" href="#添加列" aria-label="Permalink to “添加列”">​</a></h3><p>在数据库的使用过程中，添加列是一个常见的请求，但是对于一个巨大的表来说，这可能是很棘手的，同样是由于锁的问题。</p><p><strong>问题</strong>：当你添加一个新的默认值为一个函数的列时，Postgres 需要重写表。对于大表，这可能需要几个小时。</p><p><strong>方案</strong>：将操作拆分为多条基本语句，总效果一致，但控制锁的时间。</p><p>添加列：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE all_my_exes ADD COLUMN location text</span></span></code></pre></div><p>添加默认值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE all_my_exes ALTER COLUMN location SET DEFAULT texas()</span></span></code></pre></div><p>使用 <code>UPDATE</code> 来添加默认值：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>UPDATE all_my_exes SET location = DEFAULT</span></span></code></pre></div><h3 id="添加约束条件" tabindex="-1">添加约束条件 <a class="header-anchor" href="#添加约束条件" aria-label="Permalink to “添加约束条件”">​</a></h3><p><strong>问题</strong>: 你想添加一个用于数据验证的检查约束。但是如果你使用直接的方法来添加约束，它将锁定表，同时验证表中的所有现有数据。另外，如果在验证的任何时候出现错误，它将回滚。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE favorite_bands ADD CONSTRAINT name_check CHECK (name = &#39;Led Zeppelin&#39;)</span></span></code></pre></div><p><strong>方案</strong>：告诉 Postgres 这个约束，但不要验证它。在第二步中进行验证。这将在第一步中进行短暂的锁定，确保所有新的/修改过的行都符合约束条件，然后在另一步骤中进行验证，以确认所有现有的数据都通过约束条件。</p><p>告诉 Postgres 这个约束，但不要强制执行它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE favorite_bands ADD CONSTRAINT name_check CHECK (name = &#39;Led Zeppelin&#39;) NOT VALID</span></span></code></pre></div><p>然后在创建后<strong>验证</strong>它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ALTER TABLE favorite_bands VALIDATE CONSTRAINT name_check</span></span></code></pre></div><h3 id="想了解更多" tabindex="-1">想了解更多？ <a class="header-anchor" href="#想了解更多" aria-label="Permalink to “想了解更多？”">​</a></h3><p>David Christensen 和我将在 3 月 9 号到 10 到在加州帕萨迪纳参加 SCaLE 的 Postgres Days。很多来自 Postgres 社区的优秀人士也会在那里。加入我们吧！</p><hr>',32)),n("p",null,[s[1]||(s[1]=e("via: ",-1)),a(t,{href:"https://opensource.com/article/23/2/manage-large-postgres-databases"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/23/2/manage-large-postgres-databases",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=e("作者：",-1)),a(t,{href:"https://opensource.com/users/elizabethchristensencrunchydatacom"},{default:i(()=>[...s[2]||(s[2]=[e("Elizabeth Garrett Christensen",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(t,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[e("lkxed",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[e("geekpi",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(t,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const x=l(d,[["render",h]]);export{C as __pageData,x as default};
